  ('l-a2-future', 2, '{"type":"grammar","title":"Will","structure":"S + will + V","explanationVi":"Quyết định ngay lúc nói, lời hứa, đề nghị giúp đỡ, dự đoán dựa trên ý kiến cá nhân."}'::jsonb),
