  ('v-bug', 'bug', '/bʌɡ/', 'noun', 'B1', 'technology', 'A mistake in a computer program.', 'lỗi phần mềm', 'I found a bug in the login page.', 'Tôi tìm thấy một lỗi ở trang đăng nhập.', array['defect']::text[], '{}'::text[], array['fix a bug', 'report a bug']::text[]),
  ('v-deploy', 'deploy', '/dɪˈplɔɪ/', 'verb', 'B1', 'technology', 'To release software so that it runs in an environment such as production.', 'triển khai', 'We deploy to production every Tuesday.', 'Chúng tôi triển khai lên production mỗi thứ Ba.', '{}'::text[], '{}'::text[], array['deploy to production', 'deploy a fix']::text[]),
  ('v-review', 'review', '/rɪˈvjuː/', 'verb', 'B1', 'technology', 'To examine something carefully to check or improve it.', 'xem xét, đánh giá', 'Could you review my pull request?', 'Bạn xem giúp pull request của tôi được không?', '{}'::text[], '{}'::text[], array['review code', 'code review']::text[]),
  ('v-improve', 'improve', '/ɪmˈpruːv/', 'verb', 'B1', 'work', 'To become better or make something better.', 'cải thiện', 'I want to improve my speaking skills.', 'Tôi muốn cải thiện kỹ năng nói.', array['enhance']::text[], array['worsen']::text[], '{}'::text[]),
  ('v-confident', 'confident', '/ˈkɒnfɪdənt/', 'adjective', 'B1', 'feelings', 'Feeling sure about your own abilities.', 'tự tin', 'She feels confident speaking English now.', 'Giờ cô ấy cảm thấy tự tin khi nói tiếng Anh.', array['self-assured']::text[], array['insecure']::text[], array['feel confident', 'confident about']::text[]),
  ('v-regret', 'regret', '/rɪˈɡret/', 'verb', 'B2', 'feelings', 'To feel sorry about something you did or did not do.', 'hối tiếc', 'I regret not studying harder at university.', 'Tôi hối tiếc vì đã không học chăm hơn ở đại học.', '{}'::text[], '{}'::text[], array['deeply regret', 'regret doing']::text[]),
  ('v-trade-off', 'trade-off', '/ˈtreɪd ɒf/', 'noun', 'B2', 'technology', 'A balance between two things you cannot have at the same time.', 'sự đánh đổi', 'There is a trade-off between speed and accuracy.', 'Có sự đánh đổi giữa tốc độ và độ chính xác.', '{}'::text[], '{}'::text[], array['make a trade-off']::text[]),
  ('v-scalable', 'scalable', '/ˈskeɪləbl/', 'adjective', 'B2', 'technology', 'Able to handle growth in users or data without losing performance.', 'có khả năng mở rộng', 'We need a more scalable architecture.', 'Chúng ta cần một kiến trúc dễ mở rộng hơn.', '{}'::text[], '{}'::text[], array['highly scalable', 'scalable solution']::text[]),
  ('v-negotiate', 'negotiate', '/nɪˈɡəʊʃieɪt/', 'verb', 'B2', 'work', 'To discuss something to reach an agreement.', 'đàm phán', 'She negotiated a higher salary.', 'Cô ấy đã đàm phán được mức lương cao hơn.', '{}'::text[], '{}'::text[], array['negotiate a deal', 'negotiate with']::text[]),
  ('v-scarcely', 'scarcely', '/ˈskeəsli/', 'adverb', 'C1', 'feelings', 'Almost not; only just.', 'hầu như không, vừa mới', 'Scarcely had we arrived when it started to rain.', 'Chúng tôi vừa mới đến thì trời bắt đầu mưa.', array['hardly', 'barely']::text[], '{}'::text[], '{}'::text[]),
  ('v-mitigate', 'mitigate', '/ˈmɪtɪɡeɪt/', 'verb', 'C1', 'work', 'To make something bad less severe.', 'giảm nhẹ, giảm thiểu', 'We added caching to mitigate the performance issue.', 'Chúng tôi thêm cache để giảm thiểu vấn đề hiệu năng.', array['alleviate', 'reduce']::text[], array['aggravate']::text[], array['mitigate risk', 'mitigate the impact']::text[]),
  ('v-nuance', 'nuance', '/ˈnjuːɑːns/', 'noun', 'C1', 'feelings', 'A very slight difference in meaning, feeling or tone.', 'sắc thái', 'Learners often miss the nuances of phrasal verbs.', 'Người học thường bỏ lỡ sắc thái của cụm động từ.', array['subtlety']::text[], '{}'::text[], array['subtle nuance', 'cultural nuances']::text[]),
  ('v-ubiquitous', 'ubiquitous', '/juːˈbɪkwɪtəs/', 'adjective', 'C2', 'technology', 'Seeming to be everywhere at the same time.', 'có mặt khắp nơi', 'Smartphones have become ubiquitous.', 'Điện thoại thông minh đã trở nên phổ biến khắp nơi.', array['omnipresent', 'pervasive']::text[], array['rare']::text[], '{}'::text[]),
  ('v-equivocal', 'equivocal', '/ɪˈkwɪvəkl/', 'adjective', 'C2', 'feelings', 'Not clear or decided; open to more than one interpretation.', 'mơ hồ, nước đôi', 'His answer was deliberately equivocal.', 'Câu trả lời của anh ấy cố tình nước đôi.', array['ambiguous']::text[], array['unequivocal', 'clear']::text[], '{}'::text[])
insert into public.exercises (id, level_id, skill, title, title_vi, description, estimated_minutes) values
  ('ex-a1-greetings', 'A1', 'vocabulary', 'Greetings & Introductions', 'Chào hỏi & giới thiệu', 'Các câu chào hỏi thường gặp khi gặp người mới.', 4),
  ('ex-a1-to-be', 'A1', 'grammar', 'The verb "to be"', 'Động từ "to be"', 'Luyện am / is / are ở thể khẳng định, phủ định và nghi vấn.', 5),
  ('ex-a1-present-simple', 'A1', 'grammar', 'Present simple: routines', 'Hiện tại đơn: thói quen', 'Động từ thêm -s/-es với ngôi thứ ba số ít, trợ động từ do/does.', 5),
  ('ex-a1-articles', 'A1', 'grammar', 'Articles: a, an, the', 'Mạo từ a, an, the', 'Chọn mạo từ đúng dựa vào âm đầu và ngữ cảnh.', 4),
  ('ex-a1-reading-day', 'A1', 'reading', 'Reading: Linh’s day', 'Đọc hiểu: Một ngày của Linh', 'Đọc đoạn văn ngắn và trả lời câu hỏi.', 5),
  ('ex-a2-past-simple', 'A2', 'grammar', 'Past simple', 'Quá khứ đơn', 'Động từ có quy tắc, bất quy tắc và câu hỏi với "did".', 5),
  ('ex-a2-future', 'A2', 'grammar', 'Going to vs will', 'Going to và will', 'Kế hoạch đã định, quyết định tức thì và dự đoán.', 4),
  ('ex-b1-present-perfect', 'B1', 'grammar', 'Present perfect vs past simple', 'Hiện tại hoàn thành và quá khứ đơn', 'Trải nghiệm, kết quả ở hiện tại và mốc thời gian xác định.', 5),
  ('ex-b1-standup', 'B1', 'developer', 'Daily stand-up', 'Họp daily stand-up', 'Báo cáo tiến độ ngắn gọn, nêu blocker và nhờ hỗ trợ.', 5),
  ('ex-b1-code-review', 'B1', 'developer', 'Code review comments', 'Bình luận code review', 'Góp ý mang tính xây dựng, lịch sự và rõ ràng.', 4),
  ('ex-b2-conditionals', 'B2', 'grammar', 'Second & third conditionals', 'Câu điều kiện loại 2 và 3', 'Giả định không có thật ở hiện tại và trong quá khứ.', 5),
  ('ex-c1-inversion', 'C1', 'grammar', 'Negative inversion', 'Đảo ngữ phủ định', 'Never, rarely, not only, no sooner, hardly...', 4),
  ('ex-c2-cleft', 'C2', 'grammar', 'Cleft sentences', 'Câu chẻ', 'It-clefts và wh-clefts để nhấn mạnh thông tin.', 4)
insert into public.questions (id, exercise_id, position, type, prompt, context, payload, explanation_vi) values
  ('ex-a1-greetings:q1', 'ex-a1-greetings', 0, 'multiple_choice', 'Someone says "Nice to meet you." What is the best reply?', null, '{}'::jsonb, 'Đáp lại "Nice to meet you" một cách tự nhiên nhất là "Nice to meet you, too" (Tôi cũng rất vui được gặp bạn).'),
  ('ex-a1-greetings:q2', 'ex-a1-greetings', 1, 'fill_blank', 'Điền từ còn thiếu.', null, '{"sentence":"What ___ your name?","acceptedAnswers":["is","''s"]}'::jsonb, '"Name" là danh từ số ít nên dùng "is": What is your name?'),
  ('ex-a1-greetings:q3', 'ex-a1-greetings', 2, 'matching', 'Nối câu hỏi với câu trả lời phù hợp.', null, '{"pairs":[{"left":"How are you?","right":"I''m fine, thanks."},{"left":"Where are you from?","right":"I''m from Vietnam."},{"left":"What do you do?","right":"I''m a developer."}]}'::jsonb, '"How are you?" hỏi thăm sức khoẻ, "Where are you from?" hỏi quê quán, "What do you do?" hỏi nghề nghiệp.'),
  ('ex-a1-greetings:q4', 'ex-a1-greetings', 3, 'ordering', 'Sắp xếp các từ thành câu đúng.', null, '{"tokens":["I","am","from","Ho Chi Minh City"]}'::jsonb, 'Cấu trúc: Chủ ngữ + am/is/are + from + địa danh.'),
  ('ex-a1-greetings:q5', 'ex-a1-greetings', 4, 'true_false', 'Câu sau dùng đúng hay sai?', null, '{"statement":"\"Good night\" is a greeting you use when you meet someone in the evening.","answer":false}'::jsonb, '"Good night" dùng khi chào tạm biệt hoặc trước khi đi ngủ. Khi gặp ai đó buổi tối ta nói "Good evening".'),
  ('ex-a1-to-be:q1', 'ex-a1-to-be', 0, 'multiple_choice', 'They ___ students.', null, '{}'::jsonb, '"They" là chủ ngữ số nhiều nên đi với "are".'),
  ('ex-a1-to-be:q2', 'ex-a1-to-be', 1, 'fill_blank', 'Điền dạng đúng của "to be".', null, '{"sentence":"My sister ___ a nurse.","acceptedAnswers":["is"]}'::jsonb, '"My sister" = she (ngôi thứ ba số ít) → "is".'),
  ('ex-a1-to-be:q3', 'ex-a1-to-be', 2, 'error_correction', 'Câu sau có một lỗi sai. Hãy viết lại câu đúng.', null, '{"sentence":"I is very happy today.","acceptedAnswers":["I am very happy today.","I''m very happy today."]}'::jsonb, 'Chủ ngữ "I" luôn đi với "am", không dùng "is".'),
  ('ex-a1-to-be:q4', 'ex-a1-to-be', 3, 'multiple_choice', 'Chọn câu phủ định đúng.', null, '{}'::jsonb, 'Phủ định của "to be": thêm "not" sau động từ → is not = isn''t.'),
  ('ex-a1-to-be:q5', 'ex-a1-to-be', 4, 'translation', 'Dịch sang tiếng Anh.', null, '{"sourceVi":"Chúng tôi là bạn bè.","acceptedAnswers":["We are friends.","We''re friends."]}'::jsonb, '"Chúng tôi" = we → we are; "bạn bè" ở số nhiều = friends.'),
  ('ex-a1-to-be:q6', 'ex-a1-to-be', 5, 'ordering', 'Sắp xếp thành câu hỏi đúng.', null, '{"tokens":["Are","you","a","teacher","?"]}'::jsonb, 'Câu hỏi Yes/No với "to be": đưa am/is/are lên trước chủ ngữ.'),
  ('ex-a1-present-simple:q1', 'ex-a1-present-simple', 0, 'multiple_choice', 'She ___ to work by bus.', null, '{}'::jsonb, 'Với he/she/it, động từ kết thúc bằng -o thêm "-es": go → goes.'),
  ('ex-a1-present-simple:q2', 'ex-a1-present-simple', 1, 'fill_blank', 'Điền trợ động từ đúng.', null, '{"sentence":"___ you like coffee?","acceptedAnswers":["Do"]}'::jsonb, 'Câu hỏi với "you" dùng trợ động từ "Do".'),
  ('ex-a1-present-simple:q3', 'ex-a1-present-simple', 2, 'error_correction', 'Sửa lỗi sai trong câu.', null, '{"sentence":"He don''t watch TV in the morning.","acceptedAnswers":["He doesn''t watch TV in the morning.","He does not watch TV in the morning."]}'::jsonb, 'Với he/she/it, phủ định dùng "doesn''t" (does not), không dùng "don''t".'),
  ('ex-a1-present-simple:q4', 'ex-a1-present-simple', 3, 'true_false', 'Đúng hay sai?', null, '{"statement":"In \"My father usually drinks tea\", the verb is correct.","answer":true}'::jsonb, '"My father" = he → động từ thêm -s: drinks. Trạng từ tần suất "usually" đứng trước động từ thường.'),
  ('ex-a1-present-simple:q5', 'ex-a1-present-simple', 4, 'translation', 'Dịch sang tiếng Anh.', null, '{"sourceVi":"Tôi thức dậy lúc 6 giờ mỗi ngày.","acceptedAnswers":["I wake up at 6 every day.","I wake up at six every day.","I wake up at 6 o''clock every day.","I wake up at six o''clock every day.","I get up at 6 every day.","I get up at six every day.","I get up at six o''clock every day."]}'::jsonb, 'Thói quen hằng ngày dùng hiện tại đơn: I wake up / get up at six (o''clock) every day.'),
  ('ex-a1-articles:q1', 'ex-a1-articles', 0, 'multiple_choice', 'I eat ___ apple every morning.', null, '{}'::jsonb, '"Apple" bắt đầu bằng nguyên âm /æ/ nên dùng "an".'),
  ('ex-a1-articles:q2', 'ex-a1-articles', 1, 'multiple_choice', 'She is ___ university student.', null, '{}'::jsonb, '"University" phát âm /ˌjuː.../ bắt đầu bằng phụ âm /j/ nên dùng "a" dù chữ cái đầu là "u".'),
  ('ex-a1-articles:q3', 'ex-a1-articles', 2, 'fill_blank', 'Điền mạo từ.', null, '{"sentence":"I have a cat. ___ cat is black.","acceptedAnswers":["The"]}'::jsonb, 'Lần thứ hai nhắc đến "cat", người nghe đã biết là con mèo nào → dùng "the".'),
  ('ex-a1-articles:q4', 'ex-a1-articles', 3, 'true_false', 'Đúng hay sai?', null, '{"statement":"\"He is an honest man\" uses the correct article.","answer":true}'::jsonb, 'Chữ "h" trong "honest" là âm câm, từ bắt đầu bằng nguyên âm /ɒ/ → "an honest man".'),
  ('ex-a1-articles:q5', 'ex-a1-articles', 4, 'error_correction', 'Sửa lỗi sai.', null, '{"sentence":"The sun rises in a east.","acceptedAnswers":["The sun rises in the east."]}'::jsonb, 'Phương hướng duy nhất (the east, the west...) dùng "the".'),
  ('ex-a1-reading-day:q1', 'ex-a1-reading-day', 0, 'true_false', 'Đúng hay sai theo đoạn văn?', 'Linh is 24 years old. She lives in Da Nang and works in an office. Every day, she wakes up at half past six and has bánh mì for breakfast. She goes to work by motorbike. In the evening, she studies English for thirty minutes. On Sundays, she visits her parents.', '{"statement":"Linh goes to work by bus.","answer":false}'::jsonb, 'Đoạn văn viết "She goes to work by motorbike" — cô ấy đi làm bằng xe máy.'),
  ('ex-a1-reading-day:q2', 'ex-a1-reading-day', 1, 'multiple_choice', 'What time does Linh wake up?', 'Linh is 24 years old. She lives in Da Nang and works in an office. Every day, she wakes up at half past six and has bánh mì for breakfast. She goes to work by motorbike. In the evening, she studies English for thirty minutes. On Sundays, she visits her parents.', '{}'::jsonb, '"Half past six" = 6 giờ 30 phút.'),
  ('ex-a1-reading-day:q3', 'ex-a1-reading-day', 2, 'multiple_choice', 'What does Linh do on Sundays?', 'Linh is 24 years old. She lives in Da Nang and works in an office. Every day, she wakes up at half past six and has bánh mì for breakfast. She goes to work by motorbike. In the evening, she studies English for thirty minutes. On Sundays, she visits her parents.', '{}'::jsonb, 'Câu cuối: "On Sundays, she visits her parents."'),
  ('ex-a1-reading-day:q4', 'ex-a1-reading-day', 3, 'fill_blank', 'Hoàn thành câu theo đoạn văn (một từ).', 'Linh is 24 years old. She lives in Da Nang and works in an office. Every day, she wakes up at half past six and has bánh mì for breakfast. She goes to work by motorbike. In the evening, she studies English for thirty minutes. On Sundays, she visits her parents.', '{"sentence":"Linh lives in ___.","acceptedAnswers":["Da Nang","Danang"]}'::jsonb, '"She lives in Da Nang."'),
  ('ex-a2-past-simple:q1', 'ex-a2-past-simple', 0, 'multiple_choice', 'Yesterday I ___ my grandparents.', null, '{}'::jsonb, '"Yesterday" là mốc thời gian đã kết thúc → quá khứ đơn: visited.'),
  ('ex-a2-past-simple:q2', 'ex-a2-past-simple', 1, 'fill_blank', 'Điền dạng quá khứ của "go".', null, '{"sentence":"We ___ to Hoi An last month.","acceptedAnswers":["went"]}'::jsonb, '"Go" là động từ bất quy tắc: go → went → gone.'),
  ('ex-a2-past-simple:q3', 'ex-a2-past-simple', 2, 'error_correction', 'Sửa lỗi sai.', null, '{"sentence":"Did you saw the film last night?","acceptedAnswers":["Did you see the film last night?"]}'::jsonb, 'Sau "did" động từ trở về nguyên mẫu: Did you see...?'),
  ('ex-a2-past-simple:q4', 'ex-a2-past-simple', 3, 'matching', 'Nối động từ với dạng quá khứ.', null, '{"pairs":[{"left":"buy","right":"bought"},{"left":"eat","right":"ate"},{"left":"write","right":"wrote"},{"left":"take","right":"took"}]}'::jsonb, 'Đây đều là động từ bất quy tắc thường gặp, cần học thuộc.'),
  ('ex-a2-past-simple:q5', 'ex-a2-past-simple', 4, 'translation', 'Dịch sang tiếng Anh.', null, '{"sourceVi":"Tôi đã không đi làm hôm qua.","acceptedAnswers":["I didn''t go to work yesterday.","I did not go to work yesterday."]}'::jsonb, 'Phủ định quá khứ đơn: didn''t + động từ nguyên mẫu.'),
  ('ex-a2-future:q1', 'ex-a2-future', 0, 'multiple_choice', '"The phone is ringing." — "OK, I ___ answer it."', null, '{}'::jsonb, 'Quyết định đưa ra ngay lúc nói → dùng "will".'),
  ('ex-a2-future:q2', 'ex-a2-future', 1, 'multiple_choice', 'I bought a plane ticket. I ___ visit Japan in May.', null, '{}'::jsonb, 'Kế hoạch đã có từ trước (đã mua vé) → "be going to".'),
  ('ex-a2-future:q3', 'ex-a2-future', 2, 'true_false', 'Đúng hay sai?', null, '{"statement":"Look at those dark clouds! It is going to rain.","answer":true}'::jsonb, 'Dự đoán dựa trên dấu hiệu ở hiện tại (mây đen) → "be going to" là tự nhiên nhất.'),
  ('ex-a2-future:q4', 'ex-a2-future', 3, 'ordering', 'Sắp xếp thành câu đúng.', null, '{"tokens":["What","are","you","going","to","do","this weekend","?"]}'::jsonb, 'Câu hỏi: Từ để hỏi + am/is/are + chủ ngữ + going to + động từ?'),
  ('ex-b1-present-perfect:q1', 'ex-b1-present-perfect', 0, 'multiple_choice', 'I ___ to Singapore three times.', null, '{}'::jsonb, 'Nói về trải nghiệm (số lần) không nêu thời điểm → hiện tại hoàn thành.'),
  ('ex-b1-present-perfect:q2', 'ex-b1-present-perfect', 1, 'multiple_choice', 'I ___ to Singapore in 2023.', null, '{}'::jsonb, 'Có mốc thời gian cụ thể đã kết thúc (in 2023) → quá khứ đơn.'),
  ('ex-b1-present-perfect:q3', 'ex-b1-present-perfect', 2, 'fill_blank', 'Điền "for" hoặc "since".', null, '{"sentence":"She has worked here ___ 2020.","acceptedAnswers":["since"]}'::jsonb, '"Since" + mốc thời gian (2020); "for" + khoảng thời gian (five years).'),
  ('ex-b1-present-perfect:q4', 'ex-b1-present-perfect', 3, 'error_correction', 'Sửa lỗi sai.', null, '{"sentence":"I have finished the report yesterday.","acceptedAnswers":["I finished the report yesterday."]}'::jsonb, 'Không dùng hiện tại hoàn thành với "yesterday" → dùng quá khứ đơn.'),
  ('ex-b1-present-perfect:q5', 'ex-b1-present-perfect', 4, 'translation', 'Dịch sang tiếng Anh.', null, '{"sourceVi":"Bạn đã từng ăn sầu riêng chưa?","acceptedAnswers":["Have you ever eaten durian?","Have you ever tried durian?"]}'::jsonb, 'Hỏi về trải nghiệm: Have you ever + V3? — eat → ate → eaten.'),
  ('ex-b1-standup:q1', 'ex-b1-standup', 0, 'multiple_choice', 'Which sentence best describes what you did yesterday in a stand-up?', null, '{}'::jsonb, 'Việc đã làm hôm qua dùng quá khứ đơn: finished, opened. "PR" = pull request.'),
  ('ex-b1-standup:q2', 'ex-b1-standup', 1, 'fill_blank', 'Điền từ còn thiếu.', null, '{"sentence":"I''m ___ on the database migration. I need access to the staging server.","acceptedAnswers":["blocked","stuck"]}'::jsonb, '"I''m blocked on X" = tôi bị chặn/không thể tiếp tục việc X. "Stuck" cũng tự nhiên.'),
  ('ex-b1-standup:q3', 'ex-b1-standup', 2, 'matching', 'Nối cụm từ với nghĩa.', null, '{"pairs":[{"left":"on track","right":"đúng tiến độ"},{"left":"heads-up","right":"báo trước"},{"left":"pair with","right":"làm cặp cùng"},{"left":"follow up","right":"theo dõi tiếp"}]}'::jsonb, 'Đây là các cụm từ rất hay dùng trong họp nhóm phần mềm.'),
  ('ex-b1-standup:q4', 'ex-b1-standup', 3, 'ordering', 'Sắp xếp thành câu lịch sự để nhờ giúp đỡ.', null, '{"tokens":["Could","someone","help me","look into","this issue","?"]}'::jsonb, '"Could someone...?" là cách nhờ vả lịch sự; "look into" = điều tra, xem xét.'),
  ('ex-b1-standup:q5', 'ex-b1-standup', 4, 'true_false', 'Đúng hay sai?', null, '{"statement":"In a stand-up, \"Today I''m going to write unit tests for the login flow\" is a natural way to describe your plan.","answer":true}'::jsonb, 'Kế hoạch trong ngày thường dùng "I''m going to..." hoặc "I''ll...". Câu này tự nhiên và rõ ràng.'),
  ('ex-b1-code-review:q1', 'ex-b1-code-review', 0, 'multiple_choice', 'Which review comment is the most constructive?', null, '{}'::jsonb, 'Góp ý tốt đưa ra đề xuất cụ thể và lý do. Dạng câu hỏi "Could we...?" nhẹ nhàng hơn.'),
  ('ex-b1-code-review:q2', 'ex-b1-code-review', 1, 'matching', 'Nối viết tắt với nghĩa.', null, '{"pairs":[{"left":"LGTM","right":"Looks good to me"},{"left":"nit","right":"Minor, non-blocking suggestion"},{"left":"WIP","right":"Work in progress"}]}'::jsonb, 'Các viết tắt phổ biến trong pull request. "nit" (nitpick) là góp ý nhỏ, không bắt buộc sửa.'),
  ('ex-b1-code-review:q3', 'ex-b1-code-review', 2, 'fill_blank', 'Điền từ còn thiếu.', null, '{"sentence":"Good catch! I ___ fixed it in the latest commit.","acceptedAnswers":["have","''ve"]}'::jsonb, 'Kết quả vừa hoàn thành, liên quan đến hiện tại → hiện tại hoàn thành: I have fixed it.'),
  ('ex-b1-code-review:q4', 'ex-b1-code-review', 3, 'translation', 'Dịch sang tiếng Anh.', null, '{"sourceVi":"Cảm ơn bạn đã review.","acceptedAnswers":["Thanks for the review.","Thank you for the review.","Thanks for reviewing.","Thank you for reviewing."]}'::jsonb, 'Thanks/Thank you for + danh từ hoặc V-ing.'),
  ('ex-b2-conditionals:q1', 'ex-b2-conditionals', 0, 'multiple_choice', 'If I ___ more time, I would learn Japanese.', null, '{}'::jsonb, 'Loại 2 (không có thật ở hiện tại): If + quá khứ đơn, would + V.'),
  ('ex-b2-conditionals:q2', 'ex-b2-conditionals', 1, 'multiple_choice', 'If she had left earlier, she ___ the train.', null, '{}'::jsonb, 'Loại 3 (không có thật trong quá khứ): If + had V3, would have + V3.'),
  ('ex-b2-conditionals:q3', 'ex-b2-conditionals', 2, 'error_correction', 'Sửa lỗi sai.', null, '{"sentence":"If I would be you, I would accept the offer.","acceptedAnswers":["If I were you, I would accept the offer.","If I were you, I''d accept the offer."]}'::jsonb, 'Không dùng "would" trong mệnh đề "if". Lời khuyên cố định: "If I were you...".'),
  ('ex-b2-conditionals:q4', 'ex-b2-conditionals', 3, 'true_false', 'Đúng hay sai?', null, '{"statement":"\"If we had tested the code, we wouldn''t be fixing bugs now\" is a correct mixed conditional.","answer":true}'::jsonb, 'Điều kiện hỗn hợp: nguyên nhân trong quá khứ (had tested), kết quả ở hiện tại (wouldn''t be fixing).'),
  ('ex-c1-inversion:q1', 'ex-c1-inversion', 0, 'multiple_choice', 'Never ___ such a beautiful sunset.', null, '{}'::jsonb, 'Trạng từ phủ định đứng đầu câu → đảo trợ động từ lên trước chủ ngữ: Never have I seen...'),
  ('ex-c1-inversion:q2', 'ex-c1-inversion', 1, 'fill_blank', 'Điền từ còn thiếu.', null, '{"sentence":"No sooner had we sat down ___ the fire alarm went off.","acceptedAnswers":["than"]}'::jsonb, 'Cấu trúc cố định: No sooner had + S + V3 + than + quá khứ đơn.'),
  ('ex-c1-inversion:q3', 'ex-c1-inversion', 2, 'error_correction', 'Sửa lỗi sai.', null, '{"sentence":"Not only she speaks French, but she also speaks Arabic.","acceptedAnswers":["Not only does she speak French, but she also speaks Arabic.","Not only does she speak French but she also speaks Arabic."]}'::jsonb, '"Not only" đứng đầu câu cần đảo ngữ với trợ động từ: Not only does she speak...'),
  ('ex-c2-cleft:q1', 'ex-c2-cleft', 0, 'multiple_choice', 'Which sentence emphasises that the problem was the deadline (not the budget)?', null, '{}'::jsonb, 'It-cleft: It + be + thành phần nhấn mạnh + that/who + phần còn lại.'),
  ('ex-c2-cleft:q2', 'ex-c2-cleft', 1, 'ordering', 'Sắp xếp thành câu chẻ dạng "What...".', null, '{"tokens":["What","I need","is","a clear explanation","."]}'::jsonb, 'Wh-cleft: What + mệnh đề + be + thông tin được nhấn mạnh.'),
  ('ex-c2-cleft:q3', 'ex-c2-cleft', 2, 'true_false', 'Đúng hay sai?', null, '{"statement":"\"It was in 2019 when she moved to London\" is the standard form of an it-cleft.","answer":false}'::jsonb, 'Với it-cleft, dạng chuẩn dùng "that": It was in 2019 that she moved to London. "When" ít được chấp nhận trong văn viết trang trọng.')
